<?php
require_once __DIR__ . '/includes/auth.php'; require_staff();
$pdo = db(); $action = $_GET['action'] ?? '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    if (($_POST['form_action'] ?? '') === 'delete') { flash('error','Resident records are protected by the retention policy and cannot be deleted. Use Edit to update the status or address.'); redirect('residents.php'); }
    $id = (int)($_POST['id'] ?? 0); $data = [trim($_POST['barangay_id']), trim($_POST['full_name']), trim($_POST['address']), (int)$_POST['age'], trim($_POST['sector']), trim($_POST['household']), trim($_POST['civil_status']), trim($_POST['contact_number'])];
    if ($id) { $pdo->prepare('UPDATE residents SET barangay_id=?, full_name=?, address=?, age=?, sector=?, household=?, civil_status=?, contact_number=? WHERE id=?')->execute([...$data, $id]); flash('success','Resident profile updated.'); } else { $pdo->prepare('INSERT INTO residents (barangay_id,full_name,address,age,sector,household,civil_status,contact_number,status) VALUES (?,?,?,?,?,?,?,? ,\'Pending\')')->execute($data); flash('success','Resident profile created.'); }
    redirect('residents.php');
}
$editing = null; if ($action === 'edit') { $stmt=$pdo->prepare('SELECT * FROM residents WHERE id=?'); $stmt->execute([(int)$_GET['id']]); $editing=$stmt->fetch(); }
$search = trim($_GET['search'] ?? ''); $stmt=$pdo->prepare('SELECT * FROM residents WHERE full_name LIKE ? OR barangay_id LIKE ? OR household LIKE ? ORDER BY created_at DESC'); $like="%$search%"; $stmt->execute([$like,$like,$like]); $residents=$stmt->fetchAll();
$pageTitle='Residents'; $activePage='residents'; require __DIR__ . '/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Management / Resident directory</div><h1>Residents</h1><p>Keep resident records accurate, searchable, and permanently available for audit and service history.</p></div><a class="primary-button" href="residents.php?action=new">＋ Add new resident</a></section><div class="priority-banner retention-safe"><span class="priority-icon">✓</span><div><strong>Protected identity records</strong><small>Residents and staff are never deleted. Use Edit to update a status or address, and use Data retention for policy review.</small></div><a href="retention.php">View policy →</a></div>
<?php if ($action === 'new' || $editing): ?><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Resident directory</div><h2><?= $editing ? 'Edit resident profile' : 'Add new resident' ?></h2></div><a class="text-button" href="residents.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= h($editing['id'] ?? '') ?>"><input type="hidden" name="form_action" value="save"><label>Barangay ID<input name="barangay_id" required value="<?= h($editing['barangay_id'] ?? 'BRG-' . date('ymdHis')) ?>"></label><label>Full name<input name="full_name" required value="<?= h($editing['full_name'] ?? '') ?>"></label><label>Age<input type="number" min="0" max="120" name="age" required value="<?= h($editing['age'] ?? '') ?>"></label><label>Sector<select name="sector"><option>Worker</option><option>Women</option><option>Youth</option><option>Senior citizen</option><option>Solo parent</option></select></label><label class="wide">Current address<input name="address" required value="<?= h($editing['address'] ?? '') ?>"></label><label>Household<input name="household" required value="<?= h($editing['household'] ?? '') ?>"></label><label>Civil status<select name="civil_status"><option>Single</option><option>Married</option><option>Widowed</option><option>Separated</option></select></label><label>Contact number<input name="contact_number" value="<?= h($editing['contact_number'] ?? '') ?>"></label><div class="form-actions"><a class="secondary-button" href="residents.php">Cancel</a><button class="primary-button" type="submit">Save resident profile</button></div></form></section><?php endif; ?><section class="panel table-panel"><div class="table-toolbar"><form class="search-form"><input name="search" placeholder="Search name, ID, or household..." value="<?= h($search) ?>"><button class="secondary-button">⌕ Search</button></form><span class="muted">Showing <?= count($residents) ?> records</span></div><div class="table-wrap"><table><thead><tr><th>Resident</th><th>Barangay ID</th><th>Age / sector</th><th>Household</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($residents as $resident): ?><tr><td><div class="person-cell"><span class="avatar"><?= h(strtoupper(substr($resident['full_name'],0,2))) ?></span><div><strong><?= h($resident['full_name']) ?></strong><small><?= h($resident['address']) ?></small></div></div></td><td class="mono"><?= h($resident['barangay_id']) ?></td><td><?= h($resident['age']) ?><small class="cell-subtext"><?= h($resident['sector']) ?></small></td><td><?= h($resident['household']) ?></td><td><span class="status-pill <?= h(strtolower(str_replace(' ','-',$resident['status']))) ?>"><i></i><?= h($resident['status']) ?></span></td><td class="actions"><a class="text-button" href="residents.php?action=edit&id=<?= h($resident['id']) ?>">Edit</a><button class="disabled-action" type="button" disabled title="Identity records are protected by the retention policy">Delete</button></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
